urce","label":"Power source","type":"enum_or_text","tier":"recommended","filterable":true,"comparable":true},{"code":"grade_or_standard","label":"Grade / standard","type":"text_or_reference","tier":"recommended","filterable":true,"comparable":true},{"code":"dimensions","label":"Dimensions","type":"measurement_group","unit":"mm_cm_m","tier":"recommended","filterable":true,"comparable":true},{"code":"manufacturer","label":"Manufacturer","type":"text_or_reference","tier":"recommended","filterable":true,"comparable":true},{"code":"service_scope","label":"What is included?","type":"short_text","tier":"essential","filterable":true,"comparable":true},{"code":"service_area","label":"Areas served","type":"location_or_area_list","tier":"essential","filterable":true,"comparable":false},{"code":"price_basis","label":"How is the service charged?","type":"enum","values":["per_hour","per_day","per_visit","per_item","per_word","per_page","per_project","quotation"],"tier":"essential","filterable":true,"comparable":true},{"code":"duration_or_turnaround","label":"Duration / delivery time","type":"duration","tier":"recommended","filterable":true,"comparable":true},{"code":"availability","label":"Availability","type":"schedule","tier":"recommended","filterable":true,"comparable":false},{"code":"provider_qualifications_if_relevant","label":"Qualifications / licence","type":"text_or_reference","tier":"regulatory_or_recommended","filterable":false,"comparable":false},{"code":"format","label":"Format","type":"enum_or_text","tier":"essential","filterable":true,"comparable":true},{"code":"delivery_method","label":"How is it delivered?","type":"enum","values":["download","email","account_access","physical_media"],"tier":"essential","filterable":true,"comparable":true},{"code":"licence_or_usage_terms","label":"Licence / usage terms","type":"text_or_enum","tier":"essential","filterable":true,"comparable":true},{"code":"compatibility","label":"Compatibility","type":"text_or_list","tier":"recommen