e":"enum_or_reference","tier":"regulatory","filterable":false,"comparable":false},{"code":"intended_use_device","label":"Intended use","type":"text","tier":"regulatory","filterable":true,"comparable":true},{"code":"ingredients","label":"Ingredients","type":"text_or_list","tier":"recommended","filterable":true,"comparable":false},{"code":"net_weight","label":"Net weight / volume","type":"measurement","unit_family":"mass_volume","tier":"essential","filterable":true,"comparable":true},{"code":"crop_or_target","label":"Crop / target","type":"text_or_enum","tier":"essential","filterable":true,"comparable":true},{"code":"variety_or_active_ingredient","label":"Variety / active ingredient","type":"text","tier":"recommended_or_regulatory","filterable":true,"comparable":true},{"code":"pack_size_input","label":"Pack size","type":"measurement_or_count","tier":"essential","filterable":true,"comparable":true},{"code":"registration_or_approval_if_required","label":"Registration / approval","type":"text_or_reference","tier":"regulatory","filterable":false,"comparable":false}]'::jsonb) elem
) x
where d.code=x.code;

grant select on public.marketplace_taxonomy_nodes,
 public.marketplace_attribute_definitions,
 public.marketplace_attribute_profiles,
 public.marketplace_taxonomy_node_profiles,
 public.marketplace_taxonomy_aliases,
 public.marketplace_listing_kinds,
 public.marketplace_listing_kind_profiles
to anon, authenticated;

-- Medicines, medical devices, medical consumables and other health products
-- stay inactive until the relevant country's rules and seller controls are configured.
update public.marketplace_taxonomy_nodes
set is_active=false, updated_at=now()
where id like 'pharma-healthcare.medicines.%'
   or id like 'pharma-healthcare.medical-devices.%'
   or id like 'pharma-healthcare.medical-consumables.%'
   or id like 'pharma-healthcare.health-products.%';

-- Higher-risk farm inputs also require country-specific authorisation checks.
update public.marketplace_taxonomy_nodes
set is_active=false, updated_at=now()
where id in (
 'agriculture-livestock.farm-inputs.pesticides',
 'agriculture-livestock.farm-inputs.herbicides',
 'agriculture-livestock.farm-inputs.fungicides',
 'agriculture-livestock.farm-inputs.veterinary-medicines'
);
